import {html} from '/vendor/preact-htm.mjs';
import {mLong,mk,iso} from '/insights.mjs';
import {BankLogo,LinkPill,SR,Select,DEFAULT_LAYOUT,title} from '/ui.js';
import {Projections,Transactions,Chat,Settings} from '/pages2.js';

export const PALETTE=['#315e4e','#4f7f63','#6f8f3f','#93782f','#c47a4e','#9b5b4a','#6d6a9c','#4c7d96','#7a6a58','#5d7a70'];
const CARD_META={kpis:['Key numbers','wide'],networth:['Net worth','wide'],cashflow:['Money in, money out','half'],budget:['Budget vs actual','half'],subs:['Subscriptions & bills','half'],credit:['Credit utilization','half'],projection:['12-month outlook','half'],accounts:['Accounts','wide'],radar:['Recurring radar','half'],loans:['Loans & IOUs','half']};
export const H2=({id,children})=>html`<h2 id=${id} style="font:600 16px/1.3 'Geist',sans-serif;margin:0">${children}</h2>`;
export const Sub=({children,fg='#5a6b63'})=>html`<p style=${`font-size:13px;color:${fg};margin:2px 0 0`}>${children}</p>`;
export const card=(pad,extra='')=>`background:#fff;border:1px solid #e2e7df;border-radius:14px;padding:${pad};display:grid;gap:14px;min-width:0;${extra}`;
export const grid2=(gap,min=440)=>`display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,${min}px),1fr));gap:${gap};align-items:start`;
export const Kpis=({items,size=31})=>html`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:12px">${items.map(k=>html`<div style=${`background:${k.dark?'#183c35':'#fff'};color:${k.dark?'#fff':'#183c35'};border:1px solid ${k.dark?'#183c35':'#e2e7df'};border-radius:12px;padding:16px 18px;display:grid;gap:6px;min-width:0`}><div style=${`font-size:13px;color:${k.dark?'#cfe0c9':'#5a6b63'}`}>${k.label}</div><div style=${`font:400 ${size}px/1.1 'Instrument Serif',serif;letter-spacing:-.3px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere`}>${k.value}</div><div style=${`font-size:12px;color:${k.dark?'#cfe0c9':'#5a6b63'}`}>${k.note}</div></div>`)}</div>`;
export const AskBtn=({onClick,label='✦ Ask',fill='#fff',rest='#dfe5db',extra=''})=>html`<button onClick=${onClick} class="rb" style=${`--f:${fill};--r:${rest};display:inline-flex;align-items:center;gap:8px;border-radius:999px;padding:6px 14px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer;white-space:nowrap;${extra}`}>${label}</button>`;
const tag=(t,bg,fg)=>html`<span style=${`font-size:11px;font-weight:700;background:${bg};color:${fg};padding:1px 7px;border-radius:10px`}>${t}</span>`;
const empty=t=>html`<p style="margin:0;padding:16px;background:#f7f9f4;border-radius:10px;font-size:14px;color:#3d4d45">${t}</p>`;
const acctLabel={cash:'Cash',credit_card:'Credit card',credit_line:'Line of credit',loan:'Loan',investment:'Investment'};

export function loanView(A,J,l){const m=J.loanMath(l),owe=l.dir==='owe',orig=+l.original||+l.balance,pct=orig?Math.max(0,Math.min(100,(1-l.balance/orig)*100)):0,end=m.months!=null?new Date(J.TODAY.getFullYear(),J.TODAY.getMonth()+m.months,1):null;return {m,owe,pct,end,endLabel:l.balance<=0?'Done':end?end.toLocaleDateString('en-CA',{month:'short',year:'numeric'}):'—'};}
export function loanSummary(A,J){const L=A.allLoans(J),owe=L.filter(l=>l.dir==='owe'),owed=L.filter(l=>l.dir==='owed'),sum=a=>a.reduce((s,l)=>s+(+l.balance||0),0),pay=a=>a.reduce((s,l)=>s+(+l.payment||0),0),views=L.map(l=>({l,...loanView(A,J,l)})),debtEnd=views.filter(v=>v.owe&&v.end&&v.l.balance>0).sort((a,b)=>b.end-a.end)[0];return {owe:sum(owe),owed:sum(owed),monthly:pay(owe),owedMonthly:pay(owed),debtEnd,views,oweN:owe.length,owedN:owed.length};}

export function chartView(A,J,ch){if(!ch)return null;const vals=ch.points.map(p=>p.value),max=Math.max(1,...vals.map(Math.abs)),aria=`${ch.title}: `+ch.points.map(p=>`${p.label} ${A.money(p.value)}`).join(', ');if(ch.type==='line'){const lp=J.linePath(vals,560,160,10);return {title:ch.title,isLine:true,d:lp.d,area:lp.area,labels:ch.points.map(p=>p.label),aria};}return {title:ch.title,isBar:true,bars:ch.points.map((p,i)=>({h:Math.max(2,Math.abs(p.value)/max*82),v:A.short(p.value),color:p.value<0?'#c47a4e':i===ch.points.length-1?'#183c35':'#4f7f63'})),labels:ch.points.map(p=>p.label),aria};}
export const paras=text=>String(text||'').split(/\n+/).map(l=>l.trim()).filter(Boolean).map(l=>{const bullet=/^[-•*]\s+/.test(l),c=l.replace(/^[-•*]\s+/,'');return {bullet,segs:c.split('**').map((t,i)=>({t,w:i%2?700:400})).filter(x=>x.t)};});

// ===================== OVERVIEW =====================
function Overview({A,S,J,r,rows,prev,s,ps,hasPrev,all,pad,gap,mobile}){
 const delta=(a,b,goodUp=true,pp=false)=>{if(!hasPrev)return {text:'New',color:'#3d4d45',bg:'#eef1ea',sr:'no previous period data'};const d=pp?a-b:(b?(a-b)/Math.abs(b)*100:0),up=d>=0,good=goodUp?up:!up;return {text:`${up?'▲':'▼'} ${Math.abs(d).toFixed(1)}${pp?' pts':'%'}`,color:good?'#2f5d3a':'#9a3d2a',bg:good?'#e6f0dc':'#f8e6e0',sr:`${up?'up':'down'} ${Math.abs(d).toFixed(1)}${pp?' points':' percent'} versus the previous period`};};
 const kpis=[{label:'Net cash flow',value:A.money(s.surplus),d:delta(s.surplus,ps.surplus),note:'income minus spending',dark:true},{label:'Income',value:A.money(s.income),d:delta(s.income,ps.income),note:s.contributions?'incl. household contributions':'earned'},{label:'Spending',value:A.money(s.spending),d:delta(s.spending,ps.spending,false),note:`after ${A.money(s.refunds)} refunds`},{label:'Savings rate',value:s.savingsRate==null?'—':s.savingsRate.toFixed(1)+'%',d:delta(s.savingsRate||0,ps.savingsRate||0,true,true),note:'of income kept'}];
 const subsList=J.recurring(),budgets=J.budgetsAll();
 // net worth
 const nwS=J.netWorth(24),lp=J.linePath(nwS.map(x=>x.value),800,200,8),hi=Math.min(S.nwHover??nwS.length-1,nwS.length-1),sel=nwS[hi],first=nwS[0].value,lastV=nwS.at(-1).value;
 // cash flow
 let ms=J.monthly(r.start,r.end,S.inst);if(ms.length<6){const r6=J.rangeFor('6m');ms=J.monthly(r6.start,J.todayIso,S.inst);}ms=ms.filter(m=>m.month>=J.minMonth).slice(-12);if(!ms.length)ms=[{month:mk(J.TODAY),income:0,spending:0,surplus:0}];
 const hmx=Math.max(1,...ms.map(x=>x.income),...ms.map(x=>x.spending)),cfi=Math.min(S.cfHover??ms.length-1,ms.length-1),sh=n=>(n<0?'−':'+')+(Math.abs(n)>=1000?(Math.abs(n)/1000).toFixed(1)+'k':Math.round(Math.abs(n))),cs0=ms[cfi],avgIn=ms.reduce((a,x)=>a+x.income,0)/ms.length,avgOut=ms.reduce((a,x)=>a+x.spending,0)/ms.length,avgK=avgIn-avgOut;
 // budget
 const lastM=mk(new Date(J.TODAY.getFullYear(),J.TODAY.getMonth()-1,1)),curM=mk(J.TODAY),bm=S.budgetMonth==='last'?lastM:curM,bmap=Object.fromEntries(J.byCategory(all.filter(t=>t.date.startsWith(bm)&&(!S.inst||t.institution===S.inst))).map(c=>[c.name,c.value])),dim=new Date(J.TODAY.getFullYear(),J.TODAY.getMonth()+1,0).getDate(),frac=S.budgetMonth==='last'?1:J.TODAY.getDate()/dim;
 const budget=Object.entries(budgets).filter(([k,v])=>v>0&&!['Rent','Loan payments'].includes(k)).map(([name,limit])=>{const sp=bmap[name]||0,pct=sp/limit*100,over=sp>limit,pace=frac<1&&sp>limit*frac*1.15;return {name,spent:A.money(sp),limit:A.money(limit),w:Math.min(100,pct),color:over?'#b0472f':pct>85||pace?'#b07a2a':'#315e4e',amtFg:over?'#9a3d2a':'#183c35',note:over?`Over by ${A.money(sp-limit)}`:pace?`Ahead of pace · ${A.money(limit-sp)} left`:`${A.money(limit-sp)} left · ${Math.round(pct)}% used`,noteFg:over?'#9a3d2a':'#5a6b63',o:pct};}).sort((a,b)=>b.o-a.o).slice(0,6);
 // credit
 const cards=J.accounts.filter(a=>['credit_card','credit_line'].includes(a.class)&&a.limit>0&&(!S.inst||a.institution===S.inst)),tb=cards.reduce((a,c)=>a+(+c.balance||0),0),tl=cards.reduce((a,c)=>a+(+c.limit||0),0);
 // projection
 const proj0=J.projection({}),plo=Math.min(...proj0.lo),phi=Math.max(...proj0.hi),psc=J.linePath(proj0.sc,600,140,6,plo,phi),pup=J.linePath(proj0.hi,600,140,6,plo,phi),pdn=J.linePath(proj0.lo,600,140,6,plo,phi),band=pup.d+' '+[...pdn.pts].reverse().map(q=>`L${q.x},${q.y}`).join(' ')+' Z';
 // radar
 const det0=J.detectRecurring().filter(d=>!S.dismissed.includes(d.name)&&!S.tracked.includes(d.name)),pcs=subsList.filter(x=>x.priceChange>0),wk=J.upcoming(7).filter(u=>u.kind!=='income');
 const radar=[...det0.slice(0,2).map(d=>({icon:d.type==='new'?'✦':'↻',name:title(d.name),note:d.type==='new'?`New charge on ${A.fmtDate(d.first)} · could repeat`:`Looks like a new subscription · ${d.count} monthly charges`,amt:A.money(d.amount,2),ibg:'#e3ecf6',ifg:'#2c5577'})),...pcs.slice(0,2).map(x=>({icon:'▲',ibg:'#f8e6e0',ifg:'#9a3d2a',name:title(x.name),note:`Price went up ${A.money(x.priceChange,2)} a month`,amt:A.money(x.amount,2)}))].slice(0,3);
 const LS=loanSummary(A,J);
 const ids=S.layout.filter(id=>CARD_META[id]||(id.startsWith('ai:')&&S.saved.some(x=>x.id===id.slice(3))));
 const subs={kpis:`${r.label} · compared with the previous period`,networth:'Cash minus card balances and loans · estimated from your monthly cash flow',cashflow:'Select a month to open it in the calendar',budget:'Flexible categories · edit budgets in Settings',subs:`${subsList.length} active recurring charges`,credit:'Card balances against limits',projection:`Based on your last ${Math.max(1,proj0.months)} months`,accounts:'Current balances · not affected by date filters',radar:'New, changed and due soon',loans:'Including loans your banks can’t see'};
 const links={cashflow:['Explore','spending'],subs:['All bills','recurring'],radar:['Review','recurring'],loans:['Manage','loans'],projection:['Plan ahead','projections'],budget:['Edit budgets','settings']};
 const hidden=DEFAULT_LAYOUT.filter(id=>!S.layout.includes(id));
 const cardBody=id=>{switch(id){
  case 'kpis':return html`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:12px">${kpis.map(k=>{const d=k.dark?{...k.d,bg:'#d1e5a7',color:'#183c35'}:k.d;return html`<div style=${`background:${k.dark?'#183c35':'#fff'};color:${k.dark?'#fff':'#183c35'};border:1px solid ${k.dark?'#183c35':'#e2e7df'};border-radius:12px;padding:16px 18px;display:grid;gap:8px;min-width:0`}><div style=${`font-size:13px;font-weight:500;color:${k.dark?'#cfe0c9':'#5a6b63'}`}>${k.label}</div><div style="font:400 34px/1 'Instrument Serif',serif;letter-spacing:-.3px;font-variant-numeric:tabular-nums">${k.value}</div><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span style=${`font-size:12px;font-weight:700;padding:3px 8px;border-radius:20px;background:${d.bg};color:${d.color}`}><span aria-hidden="true">${d.text}</span><${SR}>${d.sr}</${SR}></span><span style=${`font-size:12px;color:${k.dark?'#cfe0c9':'#5a6b63'}`}>${k.note}</span></div></div>`;})}</div>`;
  case 'networth':return html`<div style="display:flex;align-items:baseline;gap:12px;flex-wrap:wrap"><span style="font:400 38px/1 'Instrument Serif',serif;letter-spacing:-.3px;font-variant-numeric:tabular-nums">${A.money(sel.value)}</span><span style="font-size:13px;color:#5a6b63">${hi===nwS.length-1?'today':mLong(sel.month)}</span><span style=${`font-size:12px;font-weight:700;padding:3px 8px;border-radius:20px;background:${lastV>=first?'#e6f0dc':'#f8e6e0'};color:${lastV>=first?'#2f5d3a':'#9a3d2a'}`}>${lastV>=first?'▲':'▼'} ${A.money(Math.abs(lastV-first))} in ${nwS.length>=24?'2 years':`${nwS.length} months`}</span></div>
   <div style="position:relative;height:200px"><svg viewBox="0 0 800 200" preserveAspectRatio="none" role="img" aria-label=${`Net worth over ${nwS.length} months, from ${A.money(first)} to ${A.money(lastV)}`} style="width:100%;height:100%;display:block;overflow:visible"><line x1="0" y1="192" x2="800" y2="192" stroke="#e2e7df"></line><line x1="0" y1="100" x2="800" y2="100" stroke="#eef1ea" stroke-dasharray="3 4"></line><path d=${lp.area} fill="#d1e5a7" fill-opacity=".45"></path><path d=${lp.d} fill="none" stroke="#315e4e" stroke-width="2.5" vector-effect="non-scaling-stroke"></path></svg>
    <div aria-hidden="true" style=${`position:absolute;top:0;bottom:8px;left:${lp.pts[hi].x/8}%;width:2px;background:#183c35;opacity:.25;pointer-events:none`}></div>
    <div style="position:absolute;inset:0;display:flex" onMouseLeave=${()=>A.setState({nwHover:null})}>${nwS.map((x,i)=>html`<button onMouseEnter=${()=>A.setState({nwHover:i})} onFocus=${()=>A.setState({nwHover:i})} aria-label=${`${mLong(x.month)}: ${A.money(x.value)}`} style="flex:1;border:0;background:transparent;padding:0;cursor:crosshair"></button>`)}</div></div>
   <div aria-hidden="true" style="display:flex;justify-content:space-between;font-size:12px;color:#5a6b63;margin-top:-8px">${nwS.filter((x,i)=>i%6===0||i===nwS.length-1).map(x=>html`<span>${x.label}</span>`)}</div>`;
  case 'cashflow':return html`<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px">${[['Avg in',avgIn,'#315e4e','#183c35'],['Avg out',avgOut,'#c47a4e','#183c35'],['Avg kept',avgK,avgK>=0?'#6f9a4e':'#b0472f',avgK>=0?'#2f5d3a':'#9a3d2a']].map(([l,v,c,fg])=>html`<div style="background:#f7f9f4;border-radius:10px;padding:10px 12px;min-width:0"><div style="font-size:12px;color:#5a6b63;display:flex;align-items:center;gap:6px;white-space:nowrap"><i aria-hidden="true" style=${`width:8px;height:8px;border-radius:2px;background:${c};flex:none`}></i>${l}</div><div style=${`font:600 18px/1.3 'Geist',sans-serif;letter-spacing:-.4px;font-variant-numeric:tabular-nums;color:${fg}`}>${A.money(v)}</div></div>`)}</div>
   <div aria-live="polite" style="display:flex;justify-content:space-between;align-items:baseline;gap:8px;flex-wrap:wrap;font-size:13px;border-top:1px solid #eef1ea;padding-top:12px"><b style="font:600 14px 'Geist',sans-serif">${mLong(cs0.month)}</b><span style="color:#3d4d45;font-variant-numeric:tabular-nums">In <b>${A.money(cs0.income)}</b> · Out <b>${A.money(cs0.spending)}</b> · <b style=${`color:${cs0.surplus>=0?'#2f5d3a':'#9a3d2a'}`}>${(cs0.surplus>=0?'Kept ':'Overspent ')+A.money(Math.abs(cs0.surplus))}</b></span></div>
   <div style="position:relative;height:230px;display:flex;gap:3px" onMouseLeave=${()=>A.setState({cfHover:null})}><div aria-hidden="true" style="position:absolute;left:0;right:0;top:104px;border-top:1px solid #b9c6b4;pointer-events:none"></div>
    ${ms.map((x,i)=>{const a=i===cfi,op=S.cfHover==null||a?1:.55;return html`<button onClick=${()=>A.go('spending',{calMonth:x.month,calDay:''})} onMouseEnter=${()=>A.setState({cfHover:i})} onFocus=${()=>A.setState({cfHover:i})} aria-label=${`${mLong(x.month)}: in ${A.money(x.income)}, out ${A.money(x.spending)}, kept ${A.money(x.surplus)}. Open in calendar`} style=${`flex:1;min-width:0;border:0;padding:0 1px;background:${a?'#eef3e8':'transparent'};border-radius:8px;display:grid;grid-template-rows:104px 104px 22px;cursor:pointer;transition:background .15s`}><div style="display:flex;align-items:flex-end;justify-content:center"><div style=${`width:60%;max-width:22px;background:#315e4e;border-radius:4px 4px 0 0;height:${x.income/hmx*92}%;opacity:${op}`}></div></div><div style="display:flex;align-items:flex-start;justify-content:center"><div style=${`width:60%;max-width:22px;background:#c47a4e;border-radius:0 0 4px 4px;height:${Math.max(0,x.spending)/hmx*92}%;opacity:${op}`}></div></div><span style=${`font-size:11px;font-weight:700;color:${x.surplus>=0?'#2f5d3a':'#9a3d2a'};align-self:center;text-align:center;white-space:nowrap;overflow:hidden`}>${sh(x.surplus)}</span></button>`;})}</div>
   <div aria-hidden="true" style="display:flex;gap:3px;margin-top:-10px">${ms.map((x,i)=>html`<span style=${`flex:1;min-width:0;text-align:center;font-size:12px;color:${i===cfi?'#183c35':'#5a6b63'};font-weight:${i===cfi?700:400};overflow:hidden`}>${new Date(`${x.month}-15T12:00:00`).toLocaleDateString('en-CA',{month:'short'}).slice(0,3)}</span>`)}</div>
   <p style="margin:0;font-size:12px;color:#5a6b63">Bars above the line are money in, below are money out. The number under each month is what you kept. Select a month to open it in the calendar.</p>`;
  case 'budget':return html`<div role="group" aria-label="Budget month" style="display:flex;gap:2px;background:#edf0e9;border-radius:9px;padding:3px;align-self:flex-start">${[['last',mLong(lastM).split(' ')[0]],['cur',mLong(curM).split(' ')[0]+' so far']].map(([id,l])=>{const a=S.budgetMonth===id;return html`<button onClick=${()=>A.setState({budgetMonth:id})} aria-pressed=${a} style=${`border:0;border-radius:6px;padding:6px 11px;font-size:13px;font-weight:${a?700:500};background:${a?'#fff':'transparent'};color:${a?'#183c35':'#4f5f57'};cursor:pointer`}>${l}</button>`;})}</div>
   <div style="display:grid;gap:14px">${budget.length?budget.map(b=>html`<div style="display:grid;gap:6px"><div style="display:flex;justify-content:space-between;gap:10px;font-size:14px"><span style="font-weight:600">${b.name}</span><span style="font-variant-numeric:tabular-nums;color:#3d4d45"><b style=${`color:${b.amtFg}`}>${b.spent}</b> of ${b.limit}</span></div><div style="position:relative;height:10px;background:#edf1e9;border-radius:6px;overflow:hidden"><div style=${`height:100%;width:${b.w}%;background:${b.color};border-radius:6px`}></div></div><div style=${`font-size:12px;color:${b.noteFg}`}>${b.note}</div></div>`):empty('No budgets yet. Add some in Settings → Categories & budgets.')}</div>`;
  case 'subs':return html`<div style="display:flex;gap:24px;flex-wrap:wrap"><div><div style="font-size:12px;color:#5a6b63">Per month</div><div style="font:400 31px/1.1 'Instrument Serif',serif;letter-spacing:-.8px">${A.money(subsList.reduce((a,x)=>a+x.amount,0),2)}</div></div><div><div style="font-size:12px;color:#5a6b63">Last 12 months</div><div style="font:400 31px/1.1 'Instrument Serif',serif;letter-spacing:-.8px">${A.money(subsList.reduce((a,x)=>a+x.yearly,0))}</div></div></div>
   ${subsList.length?html`<ul style="list-style:none;margin:0;padding:0;display:grid">${subsList.slice(0,7).map(x=>html`<li style="display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 12px;padding:10px 0;border-top:1px solid #eef1ea"><span style="font-size:14px;font-weight:600;display:flex;gap:6px;align-items:center;flex-wrap:wrap">${title(x.name)}${x.isNew?tag('NEW','#e3ecf6','#2c5577'):null}${x.priceChange>0?tag(`Price ▲ ${A.money(x.priceChange,2)}`,'#f8e6e0','#9a3d2a'):null}</span><span style="font-size:14px;font-weight:600;font-variant-numeric:tabular-nums;text-align:right">${A.money(x.amount,2)}</span><span style="font-size:12px;color:#5a6b63">${x.category} · ${x.account}</span><span style="font-size:12px;color:#5a6b63;text-align:right">Next ${A.fmtDate(x.next)}</span></li>`)}</ul>`:empty('No repeating bills detected yet. They appear after three monthly charges.')}`;
  case 'credit':return cards.length?html`<div style="display:flex;align-items:baseline;gap:10px"><span style="font:400 38px/1 'Instrument Serif',serif;letter-spacing:-1px">${(tb/tl*100).toFixed(1)}%</span><span style="font-size:13px;color:#5a6b63">overall · ${A.money(tb)} of ${A.money(tl)}</span></div>
   ${cards.map(c=>{const p=c.balance/c.limit*100;return html`<div style="display:grid;gap:7px"><div style="display:flex;justify-content:space-between;gap:10px;font-size:14px;flex-wrap:wrap"><span style="font-weight:600;display:flex;align-items:center;gap:8px"><${BankLogo} institution=${c.institution} size=${18} radius=${4}/>${c.institution} ${c.name}</span><span style="font-variant-numeric:tabular-nums"><b>${p.toFixed(1)}%</b> · ${A.money(c.balance)} of ${A.money(c.limit)}</span></div><div style="position:relative;height:12px;background:#edf1e9;border-radius:6px"><div style=${`height:100%;width:${Math.min(100,Math.max(1.5,p))}%;background:${p<30?'#315e4e':p<50?'#b07a2a':'#b0472f'};border-radius:6px`}></div><div aria-hidden="true" title="30% guide" style="position:absolute;left:30%;top:-3px;bottom:-3px;width:2px;background:#183c35;opacity:.5"></div></div><div style="font-size:12px;color:#5a6b63">${p<30?`Under 30% · ${A.money(c.limit-c.balance)} available`:`Above 30% · consider paying down ${A.money(c.balance-c.limit*.3)}`}</div></div>`;})}
   <p style="margin:0;font-size:12px;color:#5a6b63">The line marks 30% of each limit, a common guideline for card balances.</p>`:empty('No credit cards with a reported limit.');
  case 'projection':return html`<div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap"><span style="font:400 34px/1 'Instrument Serif',serif;letter-spacing:-1px">${A.money(proj0.sc.at(-1))}</span><span style="font-size:13px;color:#5a6b63">liquid cash projected by ${proj0.labels.at(-1)} ${J.TODAY.getFullYear()+1}</span></div>
   <svg viewBox="0 0 600 140" preserveAspectRatio="none" role="img" aria-label=${`Projected liquid cash from ${A.money(proj0.sc[0])} today to ${A.money(proj0.sc.at(-1))} in 12 months`} style="width:100%;height:140px;display:block"><path d=${band} fill="#d1e5a7" fill-opacity=".5"></path><path d=${psc.d} fill="none" stroke="#315e4e" stroke-width="2.5" vector-effect="non-scaling-stroke"></path></svg>
   <div aria-hidden="true" style="display:flex;justify-content:space-between;font-size:12px;color:#5a6b63;margin-top:-8px">${proj0.labels.filter((x,i)=>i%3===0).map(t=>html`<span>${t}</span>`)}</div>`;
  case 'accounts':{const list=J.accounts.filter(a=>!S.inst||a.institution===S.inst);return list.length?html`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,250px),1fr));gap:12px">${list.map(a=>{const debt=['credit_card','credit_line','loan'].includes(a.class);return html`<div style="border:1px solid #e2e7df;border-radius:12px;padding:14px;display:grid;grid-template-columns:minmax(0,1fr);gap:10px;min-width:0"><div style="display:flex;gap:10px;align-items:center"><span aria-hidden="true" style="width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:#fff;border:1px solid #e2e7df;flex:none;overflow:hidden"><${BankLogo} institution=${a.institution}/></span><div style="min-width:0"><div style="font-size:14px;font-weight:600;line-height:1.3;text-wrap:balance;overflow-wrap:anywhere">${a.name}</div><div style="font-size:12px;color:#5a6b63">${a.institution} · ••${a.mask||'••'}</div></div></div><div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px;flex-wrap:wrap"><span style=${`font:400 23px/1.1 'Instrument Serif',serif;letter-spacing:-.4px;font-variant-numeric:tabular-nums;color:${debt?'#7a3a28':'#183c35'}`}>${a.balance==null?'Unavailable':(debt?'−':'')+A.money(a.balance,2)}${a.currency&&a.currency!=='CAD'?` ${a.currency}`:''}</span><span style="font-size:12px;font-weight:600;color:#3d4d45;background:#eef2ea;padding:2px 8px;border-radius:10px">${acctLabel[a.class]||'Account'}</span></div></div>`;})}</div>`:empty('Connect an account to see its balance here.');}
  case 'radar':return html`<div style="display:grid;gap:8px">${radar.length?radar.map(ri=>html`<div style="display:flex;gap:12px;align-items:center;padding:10px 12px;border:1px solid #e8ece4;border-radius:12px"><span aria-hidden="true" style=${`width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:${ri.ibg};color:${ri.ifg};font-size:15px;flex:none`}>${ri.icon}</span><div style="flex:1;min-width:0"><div style="font-size:14px;font-weight:600">${ri.name}</div><div style="font-size:12px;color:#5a6b63">${ri.note}</div></div><b style="font-variant-numeric:tabular-nums;white-space:nowrap">${ri.amt}</b></div>`):empty('Nothing new or changed. You’re all caught up.')}</div>
   <div style="border-top:1px solid #eef1ea;padding-top:12px;display:grid;gap:8px"><div style="font-size:13px;font-weight:600">Due in the next 7 days · ${A.money(wk.reduce((a,u)=>a+u.amount,0))}</div><div style="display:flex;flex-wrap:wrap;gap:6px">${wk.length?wk.map(u=>html`<span style="font-size:13px;background:#f3f6ef;border:1px solid #e2e9dc;border-radius:999px;padding:5px 11px;white-space:nowrap">${A.fmtDate(u.date)} · ${title(u.name).replace(' Rent','')} <b style="font-variant-numeric:tabular-nums">${A.money(u.amount)}</b></span>`):html`<span style="font-size:13px;color:#5a6b63">Nothing due.</span>`}</div></div>`;
  case 'loans':{const top=LS.views.slice().sort((a,b)=>b.l.balance-a.l.balance).slice(0,3);return html`<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px"><div style="background:#f8efe9;border-radius:12px;padding:12px 14px;min-width:0"><div style="font-size:12px;font-weight:600;color:#7a3a28">You owe</div><div style="font:400 29px/1.2 'Instrument Serif',serif;letter-spacing:-.6px;font-variant-numeric:tabular-nums">${A.money(LS.owe)}</div><div style="font-size:12px;color:#5a4a42">${LS.oweN} loan${LS.oweN!==1?'s':''} · ${A.money(LS.monthly)}/mo</div></div><div style="background:#eef5e8;border-radius:12px;padding:12px 14px;min-width:0"><div style="font-size:12px;font-weight:600;color:#2f5d3a">Owed to you</div><div style="font:400 29px/1.2 'Instrument Serif',serif;letter-spacing:-.6px;font-variant-numeric:tabular-nums">${A.money(LS.owed)}</div><div style="font-size:12px;color:#3d4d45">${LS.owedN} IOU${LS.owedN!==1?'s':''} outstanding</div></div></div>
   ${top.length?top.map(v=>html`<div style="display:grid;gap:6px"><div style="display:flex;justify-content:space-between;gap:10px;font-size:14px"><span style="font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${v.l.name}</span><span style="font-variant-numeric:tabular-nums;white-space:nowrap">${A.money(v.l.balance)} left</span></div><div style="height:8px;background:#edf1e9;border-radius:5px;overflow:hidden"><div style=${`height:100%;width:${Math.max(2,v.pct)}%;background:${v.owe?'#c47a4e':'#315e4e'};border-radius:5px`}></div></div><div style="font-size:12px;color:#5a6b63">${v.owe?`${Math.round(v.pct)}% paid · done by ${v.endLabel}`:`${v.l.who} has repaid ${Math.round(v.pct)}% · back by ${v.endLabel}`}</div></div>`):empty('No loans yet. Add one on the Loans & IOUs page.')}`;}
 }};
 const quickAsk=e=>{e.preventDefault();if(S.quick.trim())A.ask(S.quick);else A.go('chat');};
 return html`
  <div class="rbwrap" style="position:relative">
   <div aria-hidden="true" class="rbglow" style="inset:4px;border-radius:16px;filter:blur(16px)"></div>
   <form onSubmit=${quickAsk} class="rb quick" style="--f:#183c35;--r:#183c35;position:relative;display:flex;align-items:center;gap:10px;border-radius:16px;padding:8px 8px 8px 16px;color:#fff">
    <span aria-hidden="true" style="color:#d1e5a7;font-size:18px">✦</span>
    <label style="flex:1;min-width:0"><span class="sr">Ask about your finances</span><input value=${S.quick} onInput=${e=>A.setState({quick:e.target.value})} placeholder=${mobile?'Ask anything about your money':'Ask anything — “Why was last month more expensive?”'} style="width:100%;background:transparent;border:0;outline:none;color:#fff;font-size:15px;padding:8px 0"/></label>
    <button type="submit" style="background:#d1e5a7;color:#183c35;border:0;border-radius:9px;padding:10px 16px;font-weight:700;font-size:14px;cursor:pointer;min-height:42px">Ask</button>
   </form>
  </div>
  <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
   <p style="margin:0;font-size:14px;color:#5a6b63">${S.edit?'Reorder with the arrows, remove with ✕, or add hidden cards.':`${ids.length} cards · pin chat answers here from the Chat page`}</p>
   <div style="display:flex;gap:8px">${S.edit?html`<button onClick=${()=>A.setState({layout:[...DEFAULT_LAYOUT,...S.layout.filter(x=>x.startsWith('ai:'))]})} style="background:#fff;border:1px solid #cdd6ca;padding:8px 14px;border-radius:8px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer;min-height:38px">Reset layout</button>`:null}<button onClick=${()=>A.setState({edit:!S.edit})} aria-pressed=${S.edit} style=${`background:${S.edit?'#183c35':'#fff'};border:1px solid #183c35;padding:8px 14px;border-radius:8px;font-size:13px;font-weight:600;color:${S.edit?'#fff':'#183c35'};cursor:pointer;min-height:38px`}>${S.edit?'Done':'Customize'}</button></div>
  </div>
  ${S.edit&&hidden.length?html`<div style="background:#fff;border:1px dashed #b9c6b4;border-radius:14px;padding:16px;display:flex;gap:10px;flex-wrap:wrap;align-items:center"><span style="font-size:13px;font-weight:600;margin-right:4px">Add a card:</span>${hidden.map(id=>html`<button onClick=${()=>A.setState(st=>({layout:[...st.layout,id]}))} style="background:#f3f6ef;border:1px solid #cfdccb;border-radius:20px;padding:7px 13px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer">＋ ${CARD_META[id][0]}</button>`)}</div>`:null}
  <div style=${`display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,420px),1fr));gap:${gap};align-items:start`}>
   ${ids.map((id,i)=>{const isAi=id.startsWith('ai:'),sv=isAi?S.saved.find(x=>x.id===id.slice(3)):null,meta=CARD_META[id]||[sv.title,'half'],ln=links[id],ch=sv?.chart?chartView(A,J,sv.chart):null,t=isAi?sv.title:meta[0];
    const link=isAi?()=>A.ask(sv.title):ln?()=>A.go(ln[1],ln[1]==='settings'?{setTab:'rules'}:{}):null;
    return html`<section key=${id} aria-label=${t} style=${`grid-column:${meta[1]==='wide'?'1 / -1':'auto'};background:${isAi?'#f7faf2':'#fff'};border:1px solid ${isAi?'#d8e4cc':'#e2e7df'};border-radius:14px;padding:${pad};display:flex;flex-direction:column;gap:16px;min-width:0;outline:${S.edit?'2px dashed #b9c6b4':'none'};outline-offset:2px`}>
     <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px">
      <div style="min-width:0"><h2 style="font:600 16px/1.3 'Geist',sans-serif;letter-spacing:-.2px;margin:0;color:#183c35">${t}</h2><p style="font-size:13px;line-height:1.5;color:#5a6b63;margin:2px 0 0">${isAi?'Pinned answer':subs[id]}</p></div>
      ${S.edit?html`<div style="display:flex;gap:4px;flex:none"><button onClick=${()=>A.move(id,-1)} disabled=${i===0} aria-label=${`Move ${t} up`} style="width:34px;height:34px;border:1px solid #cdd6ca;background:#fff;border-radius:8px;cursor:pointer;color:#183c35">↑</button><button onClick=${()=>A.move(id,1)} disabled=${i===ids.length-1} aria-label=${`Move ${t} down`} style="width:34px;height:34px;border:1px solid #cdd6ca;background:#fff;border-radius:8px;cursor:pointer;color:#183c35">↓</button><button onClick=${()=>A.setState(st=>({layout:st.layout.filter(x=>x!==id),saved:isAi?st.saved.filter(x=>x.id!==sv.id):st.saved}))} aria-label=${`Remove ${t}`} style="width:34px;height:34px;border:1px solid #e3c3ba;background:#fff;border-radius:8px;cursor:pointer;color:#9a3d2a">✕</button></div>`:link?html`<${LinkPill} label=${isAi?'Ask again':ln[0]} onClick=${link}/>`:null}
     </div>
     ${isAi?html`<div style="display:grid;gap:6px">${paras(sv.answer).slice(0,4).map(p=>html`<p style="margin:0;font-size:14px;line-height:1.6;color:#183c35;text-wrap:pretty">${(p.bullet?'• ':'')+p.segs.map(x=>x.t).join('')}</p>`)}</div>${ch?.isBar?html`<div style="height:120px;display:flex;align-items:flex-end;gap:4px;border-bottom:1px solid #e2e7df">${ch.bars.map((b,j)=>html`<div title=${`${ch.labels[j]} ${b.v}`} style=${`flex:1;background:#315e4e;border-radius:4px 4px 0 0;height:${b.h}%`}></div>`)}</div>`:null}<div style="font-size:12px;color:#5a6b63">Saved from Chat · ${sv.when}</div>`:cardBody(id)}
    </section>`;})}
  </div>`;
}

// ===================== SPENDING =====================
function Spending({A,S,J,r,rows,s,ps,hasPrev,all,pad,gap,mobile,compact}){
 const cats=J.byCategory(rows),tot=cats.reduce((a,c)=>a+c.value,0)||1,selCat=S.cat&&cats.some(c=>c.name===S.cat)?S.cat:((cats.find(c=>!['Rent','Loan payments'].includes(c.name))||cats[0])?.name||''),nm=Math.max(1,J.months(r.start,r.end).length),subsList=J.recurring(),budgets=J.budgetsAll();
 const kp=[{label:'Total spending',value:A.money(s.spending),note:hasPrev?`${s.spending>=ps.spending?'▲':'▼'} ${Math.abs((s.spending-ps.spending)/(ps.spending||1)*100).toFixed(1)}% vs previous period`:r.label},{label:'Average per month',value:A.money(s.spending/nm),note:`${nm} month${nm>1?'s':''}`},{label:'Largest category',value:cats[0]?cats[0].name:'—',note:cats[0]?`${A.money(cats[0].value)} · ${Math.round(cats[0].value/tot*100)}% of spending`:''},{label:'Recurring bills',value:A.money(subsList.reduce((a,x)=>a+x.amount,0)+J.fixedMonthly()),note:'per month incl. rent & loans'}];
 const r12=J.rangeFor('12m'),cm=J.months(r12.start,r12.end),catRows=all.filter(t=>t.category===selCat&&(!S.inst||t.institution===S.inst)),vals=cm.map(m=>J.byCategory(catRows.filter(t=>t.date.startsWith(m)))[0]?.value||0),b=budgets[selCat]||0,cmx=Math.max(1,...vals,b*1.1);
 const merch=J.merchants(rows,selCat).slice(0,6);
 const cal=J.calendar(S.calMonth||mk(J.TODAY)),maxS=Math.max(1,...cal.days.filter(d=>!d.blank).map(d=>d.spend)),shift=n=>{const d=new Date(`${S.calMonth}-15T12:00:00`);d.setMonth(d.getMonth()+n);return mk(d);};
 const dsel=cal.days.find(d=>d.date===S.calDay);
 const top=J.byCategory(J.inRange(all,r12.start,r12.end,S.inst)).filter(c=>!['Rent','Loan payments'].includes(c.name)).slice(0,8),grid=top.map(c=>cm.map(m=>J.byCategory(all.filter(t=>t.category===c.name&&t.date.startsWith(m)&&(!S.inst||t.institution===S.inst)))[0]?.value||0));
 const wk=J.weekday(rows),wmx=Math.max(1,...wk.map(w=>w.v)),wtop=wk.reduce((a,b)=>b.v>a.v?b:a);
 const calCell=mobile?'52px':compact?'58px':'72px';
 return html`
  <${Kpis} items=${kp} size=${29}/>
  <div style=${grid2(gap)}>
   <section aria-labelledby="cat-h" style=${card(pad)}>
    <div><${H2} id="cat-h">Categories</${H2}><${Sub}>Select one to see its trend and merchants</${Sub}></div>
    <div style="display:grid;gap:4px">${cats.length?cats.slice(0,10).map((c,i)=>{const a=c.name===selCat,color=PALETTE[i%PALETTE.length];return html`<button onClick=${()=>A.setState({cat:c.name,merchant:''})} aria-pressed=${a} class="hv-soft" style=${`display:grid;gap:6px;text-align:left;border:1px solid ${a?'#b9c6b4':'transparent'};background:${a?'#f3f6ef':'#fff'};border-radius:10px;padding:10px 12px;cursor:pointer`}><div style="display:flex;justify-content:space-between;gap:10px;font-size:14px"><span style="display:flex;align-items:center;gap:8px;font-weight:600"><i aria-hidden="true" style=${`width:10px;height:10px;border-radius:3px;background:${color}`}></i>${c.name}</span><span style="font-variant-numeric:tabular-nums"><b>${A.money(c.value)}</b> <span style="color:#5a6b63">· ${Math.round(c.value/tot*100)}%</span></span></div><div style="height:6px;background:#edf1e9;border-radius:4px"><div style=${`height:100%;width:${c.value/cats[0].value*100}%;background:${color};border-radius:4px`}></div></div></button>`;}):empty('No spending in this range.')}</div>
   </section>
   <section aria-labelledby="catd-h" style=${card(pad,'gap:16px')}>
    <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div><${H2} id="catd-h">${selCat||'Category'}</${H2}><${Sub}>Last 12 months · avg ${A.money(vals.reduce((a,x)=>a+x,0)/12)}/mo</${Sub}></div>${selCat?html`<${AskBtn} label="✦ Ask about this" rest="#cdd6ca" extra="padding:6px 12px" onClick=${()=>A.ask(`Tell me about my ${selCat} spending ${r.label.toLowerCase()}: trend, top merchants and anything unusual.`)}/>`:null}</div>
    <div style="position:relative;height:150px;display:flex;align-items:flex-end;gap:4px;border-bottom:1px solid #e2e7df">${cm.map((m,i)=>html`<div title=${`${mLong(m)}: ${A.money(vals[i])}`} style="flex:1;min-width:0;height:100%;display:flex;flex-direction:column;justify-content:flex-end"><div style=${`background:${b&&vals[i]>b?'#b0472f':'#4f7f63'};border-radius:4px 4px 0 0;height:${vals[i]/cmx*100}%`}></div></div>`)}${b>0?html`<div aria-hidden="true" style=${`position:absolute;left:0;right:0;bottom:${b/cmx*100}%;border-top:2px dashed #183c35;opacity:.55`}><span style="position:absolute;right:0;top:-20px;font-size:12px;font-weight:600;background:#fff;padding:0 4px">Budget ${A.money(b)}</span></div>`:null}</div>
    <div aria-hidden="true" style="display:flex;gap:4px;margin-top:-10px">${cm.map(m=>html`<span style="flex:1;text-align:center;font-size:12px;color:#5a6b63;overflow:hidden">${new Date(`${m}-15T12:00:00`).toLocaleDateString('en-CA',{month:'narrow'})}</span>`)}</div>
    <div><h3 style="font:600 14px 'Geist',sans-serif;margin:0 0 6px">Top merchants</h3><div style="display:grid">
     ${merch.map(m=>{const open=S.merchant===m.name,mr=rows.filter(t=>t.name===m.name&&t.kind==='expense');return html`<button onClick=${()=>A.setState({merchant:open?'':m.name})} aria-expanded=${open} class="hv-soft" style=${`display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 12px;text-align:left;border:0;border-top:1px solid #eef1ea;background:${open?'#f7f9f4':'#fff'};padding:10px 8px;cursor:pointer;font-size:14px`}><span style="font-weight:600">${title(m.name)}</span><b style="font-variant-numeric:tabular-nums">${A.money(m.value)}</b><span style="font-size:12px;color:#5a6b63">${m.count} purchase${m.count>1?'s':''} · avg ${A.money(m.value/m.count,2)}</span><span style="font-size:12px;color:#2f5d3a;text-align:right">${open?'Hide':'Details'}</span></button>
      ${open?html`<div style="background:#f7f9f4;border-radius:10px;padding:10px 12px;display:grid;gap:4px;margin:2px 0 8px">${mr.slice(0,5).map(t=>html`<div style="display:flex;justify-content:space-between;font-size:13px;gap:10px"><span style="color:#5a6b63;font-variant-numeric:tabular-nums">${A.fmtDate(t.date)}</span><span style="flex:1">${t.accountName||t.institution}</span><b style="font-variant-numeric:tabular-nums">${A.money(t.amount,2)}</b></div>`)}<${LinkPill} label=${`See all ${m.count} transactions`} extra="justify-self:start;margin-top:4px" onClick=${()=>A.go('transactions',{q:m.name,tCat:'',tType:'all',view:''})}/></div>`:null}`;})}
    </div></div>
   </section>
  </div>
  <section aria-labelledby="cal-h" style=${card(pad)}>
   <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><div><${H2} id="cal-h">Cash-flow calendar</${H2}><${Sub}>Daily spending intensity, paydays and bills</${Sub}></div>
    <div style="display:flex;align-items:center;gap:6px"><button onClick=${()=>A.setState({calMonth:shift(-1),calDay:''})} disabled=${S.calMonth<=J.minMonth} aria-label="Previous month" style="width:38px;height:38px;border:1px solid #cdd6ca;background:#fff;border-radius:8px;cursor:pointer">‹</button><span style="min-width:140px;text-align:center;font-weight:600;font-family:'Geist',sans-serif" aria-live="polite">${cal.label}</span><button onClick=${()=>A.setState({calMonth:shift(1),calDay:''})} disabled=${S.calMonth>=mk(J.TODAY)} aria-label="Next month" style="width:38px;height:38px;border:1px solid #cdd6ca;background:#fff;border-radius:8px;cursor:pointer">›</button></div></div>
   <div style="display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:#5a6b63"><span style="display:flex;align-items:center;gap:6px"><i style="width:12px;height:12px;border-radius:3px;background:#e3a988"></i>More spending</span><span style="display:flex;align-items:center;gap:6px"><b style="color:#2f5d3a">+ $</b>Income</span><span style="display:flex;align-items:center;gap:6px"><i style="width:7px;height:7px;border-radius:50%;background:#183c35"></i>Bill or subscription</span></div>
   <div role="grid" aria-label=${cal.label} style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px">
    ${(mobile?['S','M','T','W','T','F','S']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat']).map(wd=>html`<div role="columnheader" style="font-size:12px;font-weight:600;color:#5a6b63;text-align:center;padding:4px 0">${wd}</div>`)}
    ${cal.days.map(d=>{if(d.blank)return html`<div></div>`;const ratio=d.spend/maxS,a=S.calDay===d.date;return html`<button onClick=${()=>A.setState({calDay:a?'':d.date})} disabled=${d.future} aria-label=${`${new Date(`${d.date}T12:00:00`).toLocaleDateString('en-CA',{weekday:'long',month:'long',day:'numeric'})}: spent ${A.money(d.spend)}${d.income?`, income ${A.money(d.income)}`:''}${d.bills.length?`, ${d.bills.length} bill${d.bills.length>1?'s':''}`:''}`} aria-pressed=${a} style=${`min-height:${calCell};border:${a?'2px solid #183c35':'1px solid #e8ece4'};background:${d.spend?`rgba(196,122,78,${(.08+ratio*.62).toFixed(2)})`:'#fbfcfa'};border-radius:8px;padding:6px;text-align:left;display:flex;flex-direction:column;justify-content:space-between;cursor:pointer;opacity:${d.future?.45:1};min-width:0;overflow:hidden`}><span style="display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:600">${d.day}${d.bills.length?html`<i aria-hidden="true" style="width:7px;height:7px;border-radius:50%;background:#183c35"></i>`:null}</span><span style="font-size:12px;font-variant-numeric:tabular-nums;line-height:1.25"><b style="display:block;color:#2f5d3a">${d.income?'+'+A.short(d.income):''}</b>${d.spend?A.short(d.spend):''}</span></button>`;})}
   </div>
   ${dsel?html`<div style="background:#f7f9f4;border-radius:12px;padding:12px 14px;display:grid;gap:6px"><div style="font-weight:600;font-family:'Geist',sans-serif">${new Date(`${dsel.date}T12:00:00`).toLocaleDateString('en-CA',{weekday:'long',month:'long',day:'numeric'})}</div>${dsel.rows.filter(t=>!['transfer','credit_payment'].includes(t.kind)).map(t=>html`<div style="display:flex;justify-content:space-between;gap:10px;font-size:14px"><span>${title(t.name)} <span style="color:#5a6b63;font-size:12px">· ${t.category}</span></span><b style=${`font-variant-numeric:tabular-nums;color:${t.amount<0?'#2f5d3a':'#183c35'}`}>${(t.amount<0?'+':'−')+A.money(Math.abs(t.amount),2)}</b></div>`)}</div>`:null}
  </section>
  <div style=${grid2(gap)}>
   <section aria-labelledby="heat-h" style=${card(pad)}>
    <div><${H2} id="heat-h">Spending heatmap</${H2}><${Sub}>Top categories by month, last 12 months. Darker means more.</${Sub}></div>
    <div style="overflow-x:auto"><table style="border-collapse:separate;border-spacing:3px;width:100%;min-width:560px;font-size:12px"><thead><tr><th scope="col" style="text-align:left;font-weight:600;color:#5a6b63">Category</th>${cm.map(m=>html`<th scope="col" style="font-weight:600;color:#5a6b63">${new Date(`${m}-15T12:00:00`).toLocaleDateString('en-CA',{month:'short'})}</th>`)}</tr></thead><tbody>${top.map((c,i)=>{const rmx=Math.max(1,...grid[i]);return html`<tr><th scope="row" style="text-align:left;font-weight:600;white-space:nowrap;padding-right:6px">${c.name}</th>${grid[i].map((v,j)=>{const a=v/rmx,t=`${c.name}, ${mLong(cm[j])}: ${A.money(v)}`;return html`<td title=${t} style=${`height:28px;border-radius:5px;background:rgba(49,94,78,${(.06+a*.86).toFixed(2)});text-align:center;font-size:11px`}><${SR}>${t}</${SR}></td>`;})}</tr>`;})}</tbody></table></div>
   </section>
   <section aria-labelledby="wk-h" style=${card(pad)}>
    <div><${H2} id="wk-h">Spending rhythm</${H2}><${Sub}>Average flexible spending by weekday (excludes rent, loans, bills)</${Sub}></div>
    <div style="height:180px;display:grid;grid-template-columns:repeat(7,1fr);gap:8px;align-items:end">${wk.map(w=>html`<div style="height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:6px;min-width:0"><span style="font-size:12px;font-weight:600;font-variant-numeric:tabular-nums">${A.short(w.v)}</span><div style=${`width:100%;max-width:44px;border-radius:6px 6px 2px 2px;background:${w===wtop&&w.v>0?'#c47a4e':'#4f7f63'};height:${Math.max(3,w.v/wmx*78)}%`}></div><span style="font-size:12px;color:#5a6b63">${w.d}</span></div>`)}</div>
   </section>
  </div>`;
}

// ===================== RECURRING =====================
function Recurring({A,S,J,pad,gap,rowPad}){
 const list=J.recurring(),det=J.detectRecurring().filter(d=>!S.dismissed.includes(d.name)&&!S.tracked.includes(d.name)),per=list.reduce((a,x)=>a+x.amount,0),fixed=J.fixedMonthly(),e30=new Date(J.TODAY);e30.setDate(e30.getDate()+30);
 const up=J.upcoming(30);
 A.allLoans(J).filter(l=>!l.connected&&l.dir==='owe'&&l.balance>0&&l.payment>0).forEach(l=>{const dt=new Date(J.TODAY.getFullYear(),J.TODAY.getMonth(),Math.min(28,l.day||1),12);if(dt<=J.TODAY)dt.setMonth(dt.getMonth()+1);if(dt<=e30)up.push({date:iso(dt),name:`${l.name} (${l.who})`,amount:+l.payment,kind:'iou',category:'Loan'});});
 up.sort((a,b)=>a.date.localeCompare(b.date)||b.amount-a.amount);
 const groups=[];up.forEach(u=>{let g=groups.find(x=>x.date===u.date);if(!g){g={date:u.date,items:[]};groups.push(g);}g.items.push(u);});
 const kl={rent:'Rent',loan:'Loan payment',income:'Payday',sub:'Subscription',iou:'Personal loan'},dc={rent:'#c47a4e',loan:'#9b5b4a',income:'#315e4e',sub:'#4c7d96',iou:'#6d6a9c'};
 const upOut=up.filter(u=>u.amount>0).reduce((a,u)=>a+u.amount,0),upIn=-up.filter(u=>u.amount<0).reduce((a,u)=>a+u.amount,0);let bal=J.cash();
 const prices=list.filter(x=>x.priceChange>0);
 const pillBase='display:inline-flex;align-items:center;gap:8px;border:1px solid #dfe5db;background:#fff;border-radius:999px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer;white-space:nowrap;transition:background .15s,color .15s,border-color .15s;flex:none;padding:7px 14px';
 return html`
  <${Kpis} items=${[{label:'Subscriptions & bills',value:A.money(per),note:'per month',dark:true},{label:'Per year',value:A.money(per*12),note:`${list.length} recurring charges`},{label:'With rent & loans',value:A.money(per+fixed),note:'fixed costs each month'},{label:'Due in the next 30 days',value:A.money(upOut),note:`${up.filter(u=>u.amount>0).length} payments`}]}/>
  <div style=${grid2(gap)}>
   <section aria-labelledby="rad-h" style=${card(pad,'align-content:start')}>
    <div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start"><div><${H2} id="rad-h">New & possible subscriptions</${H2}><${Sub}>Charges that started recently and look like they’ll repeat</${Sub}></div><span style="font-size:12px;font-weight:700;background:#e3ecf6;color:#2c5577;padding:3px 9px;border-radius:20px;white-space:nowrap">${det.length?`${det.length} to review`:'All clear'}</span></div>
    ${!det.length?html`<div style="background:#f3f6ef;border-radius:12px;padding:18px;text-align:center;font-size:14px;color:#3d4d45"><b style="display:block;font-size:15px;color:#183c35">You’re all caught up</b>Nothing new has started repeating. We’ll flag it here when something does.</div>`:null}
    ${det.map(d=>{const nm=title(d.name);return html`<article style="border:1px solid #e2e7df;border-radius:12px;padding:14px;display:grid;gap:10px">
     <div style="display:flex;gap:12px;align-items:flex-start"><span aria-hidden="true" style="width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:#e3ecf6;color:#2c5577;font-size:16px;flex:none">${d.type==='new'?'✦':'↻'}</span><div style="flex:1;min-width:0"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><b style="font-size:15px">${nm}</b><span style=${`font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;background:${d.type==='new'?'#fbefd9':d.confidence==='High'?'#e6f0dc':'#eef1ea'};color:${d.type==='new'?'#7a5520':d.confidence==='High'?'#2f5d3a':'#3d4d45'}`}>${d.type==='new'?'New charge':`${d.confidence} confidence`}</span></div><div style="font-size:13px;color:#5a6b63">${d.category} · ${d.account} · first charged ${A.fmtDate(d.first)}</div></div><div style="text-align:right;flex:none"><b style="font-size:15px;font-variant-numeric:tabular-nums">${A.money(d.amount,2)}</b><div style="font-size:12px;color:#5a6b63">${A.money(d.yearly)}/yr</div></div></div>
     <p style="margin:0;font-size:13px;color:#3d4d45;background:#f7f9f4;border-radius:8px;padding:8px 10px">${d.type==='new'?`One charge so far, on ${A.fmtDate(d.first)}. Free trials often turn into monthly charges. If it repeats, the next one would be around ${A.fmtDate(d.next)}.`:`Charged ${d.count} months in a row for about the same amount, around day ${d.day} of the month. Next one expected ${A.fmtDate(d.next)}.`}</p>
     <div style="display:flex;gap:8px;flex-wrap:wrap"><button onClick=${()=>{A.setState(st=>({tracked:[...st.tracked,d.name]}));A.toast(`Now tracking ${nm}`);}} class="hv-dark" style=${pillBase+';background:#183c35;color:#fff;border-color:#183c35'}>✓ Track as subscription</button><button onClick=${()=>{A.setState(st=>({dismissed:[...st.dismissed,d.name]}));A.toast('Got it. We won’t flag this again.');}} class="hv-quiet" style=${pillBase}>Not recurring</button><${AskBtn} onClick=${()=>A.ask(`Tell me about my ${nm} charges. Is it a new subscription, what will it cost per year, and is it worth keeping next to my other subscriptions?`)}/></div>
    </article>`;})}
   </section>
   <section aria-labelledby="pc-h" style=${card(pad,'align-content:start')}>
    <div><${H2} id="pc-h">Price changes</${H2}><${Sub}>Subscriptions that cost more than they used to (last 12 months)</${Sub}></div>
    ${prices.length?prices.map(p=>html`<div style="display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 12px;padding:10px 0;border-top:1px solid #eef1ea"><b style="font-size:14px">${title(p.name)}</b><span style="font-size:14px;font-variant-numeric:tabular-nums;text-align:right"><s style="color:#5a6b63;margin-right:6px">${A.money(p.amount-p.priceChange,2)}</s><b>${A.money(p.amount,2)}</b></span><span style="font-size:12px;color:#5a6b63">${p.category} · ${p.account}</span><span style="font-size:12px;font-weight:700;color:#9a3d2a;text-align:right">+${A.money(p.priceChange*12,2)} a year</span></div>`):empty('No price increases spotted.')}
    ${S.tracked.length?html`<div style="border-top:1px solid #eef1ea;padding-top:14px;display:grid;gap:8px"><h3 style="font:600 14px 'Geist',sans-serif;margin:0">Tracked by you</h3><div style="display:flex;gap:6px;flex-wrap:wrap">${S.tracked.map(n=>html`<span style="display:inline-flex;align-items:center;gap:6px;font-size:13px;background:#f3f6ef;border:1px solid #e2e9dc;border-radius:999px;padding:4px 6px 4px 11px">${title(n)}<button onClick=${()=>A.setState(st=>({tracked:st.tracked.filter(x=>x!==n)}))} aria-label=${`Stop tracking ${title(n)}`} style="border:0;background:transparent;cursor:pointer;color:#5a6b63">✕</button></span>`)}</div></div>`:null}
    ${S.dismissed.length?html`<div style="border-top:1px solid #eef1ea;padding-top:14px;display:grid;gap:8px"><h3 style="font:600 14px 'Geist',sans-serif;margin:0">Marked as not recurring</h3><div style="display:flex;gap:6px;flex-wrap:wrap">${S.dismissed.map(n=>html`<span style="display:inline-flex;align-items:center;gap:6px;font-size:13px;background:#fff;border:1px solid #e2e9dc;border-radius:999px;padding:4px 6px 4px 11px">${title(n)}<button onClick=${()=>A.setState(st=>({dismissed:st.dismissed.filter(x=>x!==n)}))} aria-label=${`Flag ${title(n)} again`} style="border:0;background:transparent;cursor:pointer;color:#5a6b63">↺</button></span>`)}</div></div>`:null}
   </section>
  </div>
  <section aria-labelledby="up-h" style=${card(pad,'align-content:start')}>
   <div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-start"><div><${H2} id="up-h">Coming up · next 30 days</${H2}><${Sub}>Bills, loan payments and paydays, with your chequing + savings balance after each day</${Sub}></div><div style="display:flex;gap:14px;font-size:13px;flex-wrap:wrap"><span>Going out <b style="font-variant-numeric:tabular-nums">${A.money(upOut)}</b></span><span>Coming in <b style="color:#2f5d3a;font-variant-numeric:tabular-nums">${A.money(upIn)}</b></span></div></div>
   ${groups.length?html`<ol style="list-style:none;margin:0;padding:0;display:grid">${groups.map(g=>{g.items.forEach(u=>{bal-=u.amount;});const d=new Date(`${g.date}T12:00:00`),pay=g.items.some(u=>u.kind==='income');return html`<li style="display:grid;grid-template-columns:56px minmax(0,1fr) auto;gap:14px;padding:12px 0;border-top:1px solid #eef1ea;align-items:start">
    <div style=${`text-align:center;background:${pay?'#e6f0dc':'#f3f6ef'};border-radius:10px;padding:6px 0`}><div style=${`font-size:11px;font-weight:700;letter-spacing:.5px;color:${pay?'#2f5d3a':'#4f5f57'}`}>${d.toLocaleDateString('en-CA',{weekday:'short'}).replace('.','').toUpperCase()}</div><div style="font:400 24px/1.1 'Instrument Serif',serif;color:#183c35">${d.getDate()}</div></div>
    <div style="display:grid;gap:4px;min-width:0">${g.items.map(u=>html`<div style="display:flex;justify-content:space-between;gap:10px;font-size:14px"><span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"><span aria-hidden="true" style=${`display:inline-block;width:8px;height:8px;border-radius:50%;background:${dc[u.kind]};margin-right:8px`}></span>${title(u.name).replace(' Rent','')} <span style="color:#5a6b63;font-size:12px">· ${kl[u.kind]}</span></span><b style=${`font-variant-numeric:tabular-nums;color:${u.amount<0?'#2f5d3a':'#183c35'};white-space:nowrap`}>${(u.amount<0?'+':'−')+A.money(Math.abs(u.amount),2)}</b></div>`)}</div>
    <div style="text-align:right;min-width:92px"><div style="font-size:11px;color:#5a6b63">Balance after</div><b style="font-variant-numeric:tabular-nums;font-size:14px">${A.money(bal)}</b></div></li>`;})}</ol>`:empty('Nothing expected in the next 30 days.')}
  </section>
  <section aria-labelledby="allr-h" style=${card(pad,'align-content:start')}>
   <div><${H2} id="allr-h">All recurring charges</${H2}><${Sub}>Sorted by monthly cost</${Sub}></div>
   <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:14px;min-width:640px"><thead><tr>${[['Name','left'],['Category','left'],['Next charge','left'],['Monthly','right'],['Per year','right']].map(([h,al])=>html`<th scope="col" style=${`text-align:${al};padding:10px 8px;background:#f5f7f2;font-size:12px;color:#3d4d45`}>${h}</th>`)}</tr></thead><tbody>
    ${list.length?list.map(x=>html`<tr style="border-bottom:1px solid #eef1ea"><td style=${`padding:${rowPad}`}><b>${title(x.name)}</b>${x.you?html` <span style="font-size:11px;font-weight:700;background:#e3ecf6;color:#2c5577;padding:2px 7px;border-radius:10px;margin-left:4px">Added by you</span>`:null}<div style="font-size:12px;color:#5a6b63">${x.account} · since ${new Date(`${x.since}T12:00:00`).toLocaleDateString('en-CA',{month:'short',year:'numeric'})}</div></td><td style=${`padding:${rowPad};color:#3d4d45`}>${x.category}</td><td style=${`padding:${rowPad};color:#3d4d45;white-space:nowrap`}>${A.fmtDate(x.next)}</td><td style=${`padding:${rowPad};text-align:right;font-variant-numeric:tabular-nums;font-weight:600`}>${A.money(x.amount,2)}</td><td style=${`padding:${rowPad};text-align:right;font-variant-numeric:tabular-nums`}>${A.money(x.amount*12)}</td></tr>`):html`<tr><td colspan="5" style="padding:20px;text-align:center;color:#5a6b63">No recurring charges detected yet.</td></tr>`}
   </tbody></table></div>
  </section>`;
}

// ===================== LOANS =====================
const inputSt='width:100%;border:1px solid #cdd6ca;background:#fff;border-radius:10px;padding:10px 12px;font-size:14px;font-weight:400;min-height:44px;outline:none;color:#183c35;transition:border-color .15s,box-shadow .15s';
export const fieldLabel='display:grid;gap:6px;font-size:13px;font-weight:600;color:#3d4d45';
export const MoneyInput=({value,onInput,placeholder='0',label})=>html`<span style="position:relative;display:flex;align-items:center"><span aria-hidden="true" style="position:absolute;left:12px;color:#5a6b63">$</span><input type="number" min="0" step="0.01" inputmode="decimal" value=${value} onInput=${onInput} placeholder=${placeholder} aria-label=${label} class="fi" style=${inputSt+';padding-left:26px'}/></span>`;
export {inputSt};
function Loans({A,S,J,pad,gap}){
 const LS=loanSummary(A,J),fl=S.loanFilter,fm=S.loanForm,net=LS.owed-LS.owe;
 const setF=(k,v)=>A.setState(st=>({loanForm:{...st.loanForm,[k]:v}}));
 const save=e=>{e.preventDefault();const v=S.loanForm,b=+v.balance;if(!v.name.trim())return A.setState({loanErr:'Give it a name so you can recognise it later.'});if(!(b>0))return A.setState({loanErr:'Enter how much is still owed.'});const l={id:'l'+Date.now(),dir:v.dir,name:v.name.trim().slice(0,120),who:(v.who.trim()||(v.dir==='owe'?'Lender':'Someone')).slice(0,120),original:Math.max(b,+v.original||b),balance:b,payment:Math.max(0,+v.payment||0),rate:Math.max(0,+v.rate||0),day:+v.day||1,connected:false};A.setState(st=>({loans:[...st.loans,l],loanForm:null,loanErr:''}));A.toast(`Added ${l.name}`);};
 const toggleForm=()=>A.setState({loanForm:fm?null:{dir:'owe',name:'',who:'',balance:'',original:'',payment:'',rate:'',day:1},loanErr:''});
 const ord=n=>n+(n%10===1&&n!==11?'st':n%10===2&&n!==12?'nd':n%10===3&&n!==13?'rd':'th');
 const dayOpts=[...Array(28)].map((_,i)=>({value:i+1,label:i===0?'1st of the month':ord(i+1)}));
 const pill='display:inline-flex;align-items:center;gap:8px;border:1px solid #dfe5db;background:#fff;border-radius:999px;font-size:13px;font-weight:600;color:#183c35;cursor:pointer;white-space:nowrap;transition:background .15s,color .15s,border-color .15s;flex:none;padding:7px 14px';
 return html`
  <${Kpis} items=${[{label:'You owe',value:A.money(LS.owe),note:`${A.money(LS.monthly)} in payments each month`,dark:true},{label:'Owed to you',value:A.money(LS.owed),note:LS.owedMonthly?`about ${A.money(LS.owedMonthly)}/mo coming back`:'nothing outstanding'},{label:'Net position',value:(net>=0?'+':'−')+A.money(Math.abs(net)),note:'owed to you minus what you owe'},{label:'Debt-free by',value:LS.debtEnd?LS.debtEnd.endLabel:'—',note:LS.debtEnd?`when your ${LS.debtEnd.l.name} is paid off`:LS.oweN?'add monthly payments to estimate':'no debts'}]}/>
  <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
   <div role="group" aria-label="Filter loans" style="display:flex;gap:2px;background:#edf0e9;border:1px solid #dfe5db;border-radius:10px;padding:3px">${[['all','All'],['owe','I owe'],['owed','Owed to me']].map(([id,label])=>{const a=fl===id;return html`<button onClick=${()=>A.setState({loanFilter:id})} aria-pressed=${a} style=${`border:0;border-radius:7px;padding:7px 13px;font-size:14px;font-weight:${a?700:500};background:${a?'#fff':'transparent'};color:${a?'#183c35':'#4f5f57'};box-shadow:${a?'0 1px 3px #183c3522':'none'};cursor:pointer;min-height:36px`}>${label}</button>`;})}</div>
   <button onClick=${toggleForm} aria-expanded=${!!fm} style="background:#183c35;border:1px solid #183c35;padding:9px 16px;border-radius:10px;font-size:14px;font-weight:600;color:#fff;cursor:pointer;min-height:42px">${fm?'Close':'＋ Add a loan'}</button>
  </div>
  ${fm?html`<form onSubmit=${save} aria-label="Add a loan" style=${`background:#fff;border:1px solid #cdd6ca;border-radius:16px;padding:${pad};display:grid;gap:18px;box-shadow:0 14px 40px #183c3514;animation:jsfin .2s ease-out`}>
   <div><${H2}>Add a loan or IOU</${H2}><${Sub}>For anything your banks can’t see: family loans, student loans, money you lent a friend.</${Sub}></div>
   <div role="radiogroup" aria-label="Direction" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:10px">${[['owe','I borrowed money','Family loan, student loan, line of credit…'],['owed','I lent money','A friend or family member owes you']].map(([id,label,note])=>{const a=fm.dir===id;return html`<button type="button" role="radio" aria-checked=${a} onClick=${()=>setF('dir',id)} class="hv-border2" style=${`display:flex;gap:12px;align-items:center;text-align:left;border:${a?'2px':'1px'} solid ${a?'#315e4e':'#e2e7df'};border-radius:12px;padding:14px;background:${a?'#f3f6ef':'#fff'};cursor:pointer;transition:border-color .15s`}><span aria-hidden="true" style=${`width:22px;height:22px;border-radius:50%;border:2px solid ${a?'#315e4e':'#9fb09a'};display:grid;place-items:center;flex:none`}><span style=${`width:10px;height:10px;border-radius:50%;background:${a?'#315e4e':'transparent'}`}></span></span><span><b style="display:block;font-size:14px">${label}</b><span style="font-size:13px;color:#5a6b63">${note}</span></span></button>`;})}</div>
   <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:14px;align-items:end">
    <label style=${fieldLabel}>What’s it for?<input value=${fm.name} onInput=${e=>setF('name',e.target.value)} maxlength="120" placeholder="e.g. Help with first & last rent" class="fi" style=${inputSt}/></label>
    <label style=${fieldLabel}>${fm.dir==='owed'?'Who borrowed it?':'Who lent it to you?'}<input value=${fm.who} onInput=${e=>setF('who',e.target.value)} maxlength="120" placeholder=${fm.dir==='owed'?'e.g. Arjun':'e.g. Mom & Dad, OSAP'} class="fi" style=${inputSt}/></label>
    <label style=${fieldLabel}>Amount still owed<${MoneyInput} value=${fm.balance} onInput=${e=>setF('balance',e.target.value)}/></label>
    <label style=${fieldLabel}><span style="display:flex;gap:6px;align-items:baseline;white-space:nowrap">Original amount <span style="font-weight:400;color:#5a6b63">optional</span></span><${MoneyInput} value=${fm.original} onInput=${e=>setF('original',e.target.value)} placeholder="Same as above"/></label>
    <label style=${fieldLabel}>Monthly payment<${MoneyInput} value=${fm.payment} onInput=${e=>setF('payment',e.target.value)}/></label>
    <label style=${fieldLabel}><span style="display:flex;gap:6px;align-items:baseline;white-space:nowrap">Interest rate <span style="font-weight:400;color:#5a6b63">optional</span></span><span style="position:relative;display:flex;align-items:center"><input type="number" min="0" step="0.1" inputmode="decimal" value=${fm.rate} onInput=${e=>setF('rate',e.target.value)} placeholder="0" class="fi" style=${inputSt+';padding-right:30px'}/><span aria-hidden="true" style="position:absolute;right:12px;color:#5a6b63">%</span></span></label>
    <div style="display:grid;gap:6px"><${Select} value=${fm.day} options=${dayOpts} onChange=${v=>setF('day',v)} label="Payment day" width="100%" minWidth="0"/></div>
   </div>
   ${S.loanErr?html`<p role="alert" style="margin:0;font-size:14px;color:#9a3d2a;background:#fbefeb;border:1px solid #efcfc5;border-radius:10px;padding:10px 12px">${S.loanErr}</p>`:null}
   <div style="display:flex;gap:8px;justify-content:flex-end"><button type="button" onClick=${toggleForm} style="background:#fff;border:1px solid #cdd6ca;padding:9px 14px;border-radius:10px;font-size:14px;font-weight:600;color:#183c35;cursor:pointer;min-height:42px">Cancel</button><button type="submit" style="background:#183c35;border:1px solid #183c35;padding:9px 18px;border-radius:10px;font-size:14px;font-weight:600;color:#fff;cursor:pointer;min-height:42px">Add loan</button></div>
  </form>`:null}
  <div style=${`display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,400px),1fr));gap:${gap};align-items:start`}>
   ${LS.views.filter(v=>fl==='all'||v.l.dir===fl).map(v=>{const l=v.l,owe=v.owe,ex=S.extra[l.id]||0,mx=J.loanMath(l,ex),paying=S.payFor===l.id,saved=v.m.months&&mx.months?v.m.months-mx.months:0,rate=l.rate==null?null:+l.rate;
    const savePay=e=>{e.preventDefault();const a=+S.payAmt;if(!(a>0))return;A.setState(st=>({loans:st.loans.map(x=>x.id===l.id?{...x,balance:Math.max(0,Math.round((x.balance-a)*100)/100)}:x),payFor:''}));A.toast(`${A.money(a,2)} recorded`);};
    return html`<article key=${l.id} aria-label=${l.name} style=${card(pad)}>
     <div style="display:flex;gap:12px;align-items:flex-start"><span aria-hidden="true" style=${`width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:${owe?'#f8e7e3':'#e6f0dc'};color:${owe?'#a3412f':'#2f5d3a'};font-size:17px;flex:none`}>${owe?'↗':'↙'}</span><div style="flex:1;min-width:0"><${H2}>${l.name}</${H2}><div style="font-size:13px;color:#5a6b63">${owe?`Owed to ${l.who}`:`${l.who} owes you`}</div></div><span style=${`font-size:11px;font-weight:700;padding:3px 8px;border-radius:10px;background:${l.connected?'#e3ecf6':'#eef1ea'};color:${l.connected?'#2c5577':'#3d4d45'};white-space:nowrap`}>${l.connected?`Connected · ${l.institution||'bank'}`:'Added by you'}</span></div>
     <div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap"><div><div style="font-size:12px;color:#5a6b63">${owe?'Left to pay':'Still to come back'}</div><div style="font:400 36px/1.1 'Instrument Serif',serif;letter-spacing:-.3px;font-variant-numeric:tabular-nums">${A.money(l.balance,2)}</div></div><div style="text-align:right;font-size:13px;color:#3d4d45">${owe?`${A.money(l.original-l.balance)} paid of ${A.money(l.original)}`:`${A.money(l.original-l.balance)} repaid of ${A.money(l.original)}`}</div></div>
     <div role="progressbar" aria-valuenow=${Math.round(v.pct)} aria-valuemin="0" aria-valuemax="100" aria-label=${`${Math.round(v.pct)}% ${owe?'paid off':'repaid'}`} style="height:10px;background:#edf1e9;border-radius:6px;overflow:hidden"><div style=${`height:100%;width:${v.pct}%;background:${owe?'#c47a4e':'#315e4e'};border-radius:6px;transition:width .3s`}></div></div>
     <div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px">${[{label:owe?'Monthly':'Expected monthly',value:l.payment?A.money(l.payment):'—'},{label:'Interest',value:rate==null?'—':rate?`${rate}%`:'None'},{label:owe?'Paid off by':'Back by',value:v.endLabel}].map(st=>html`<div style="background:#f7f9f4;border-radius:10px;padding:9px 11px;min-width:0"><div style="font-size:12px;color:#5a6b63">${st.label}</div><b style="font-size:14px;font-variant-numeric:tabular-nums">${st.value}</b></div>`)}</div>
     ${owe&&l.payment>0&&l.balance>0?html`<div style="border:1px solid #dfe6d6;background:#f0f4e8;border-radius:12px;padding:12px;display:grid;gap:8px"><div style="font-size:13px;font-weight:600">What if you paid a bit more each month?</div><div role="group" aria-label="Extra monthly payment" style="display:flex;gap:6px;flex-wrap:wrap">${[0,50,100,250].map(x=>{const a=ex===x;return html`<button onClick=${()=>A.setState(st=>({extra:{...st.extra,[l.id]:x}}))} aria-pressed=${a} style=${`border:1px solid ${a?'#183c35':'#cdd6ca'};background:${a?'#183c35':'#fff'};color:${a?'#fff':'#183c35'};border-radius:999px;padding:6px 12px;font-size:13px;font-weight:600;cursor:pointer`}>${x?`+${A.money(x)}`:'As is'}</button>`;})}</div><div aria-live="polite" style=${`font-size:13px;color:${ex&&saved>0?'#2f5d3a':'#3d4d45'}`}>${ex&&saved>0?`You’d be done ${saved} month${saved>1?'s':''} sooner${rate?` and save ${A.money(v.m.interest-mx.interest)} in interest`:''}.`:rate?`At ${rate}% you’ll pay about ${A.money(v.m.interest||0)} in interest at this pace.`:rate==null?'Interest isn’t reported for this loan, so this assumes none.':'No interest on this one, so paying more just finishes it sooner.'}</div></div>`:null}
     ${paying?html`<form onSubmit=${savePay} style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;background:#f7f9f4;border-radius:12px;padding:12px"><label style=${fieldLabel+';flex:1;min-width:160px'}>${owe?'Payment amount':'Amount they paid back'}<${MoneyInput} value=${S.payAmt} onInput=${e=>A.setState({payAmt:e.target.value})}/></label><button type="button" onClick=${()=>A.setState({payFor:''})} style="background:#fff;border:1px solid #cdd6ca;padding:9px 14px;border-radius:10px;font-size:14px;font-weight:600;color:#183c35;cursor:pointer;min-height:44px">Cancel</button><button type="submit" style="background:#183c35;border:1px solid #183c35;padding:9px 16px;border-radius:10px;font-size:14px;font-weight:600;color:#fff;cursor:pointer;min-height:44px">Save</button></form>`:null}
     ${!l.connected?html`<div style="display:flex;gap:8px;flex-wrap:wrap"><button onClick=${()=>A.setState({payFor:paying?'':l.id,payAmt:String(l.payment||'')})} class="hv-pill" style=${pill}>${owe?'Record a payment':'Record repayment'}</button>${!owe?html`<button onClick=${()=>A.toast(`Reminders aren’t sent automatically. Message ${l.who} yourself when you’re ready.`)} class="hv-pill" style=${pill}>Send a friendly reminder</button>`:null}<button onClick=${()=>{A.setState(st=>({loans:st.loans.filter(x=>x.id!==l.id)}));A.toast(`Removed ${l.name}`);}} aria-label=${`Remove ${l.name}`} class="hv-danger" style=${pill+';color:#9a3d2a;border-color:#efcfc5'}>Remove</button></div>`:html`<p style="margin:0;font-size:12px;color:#5a6b63">Balance comes from your bank and updates when you sync.</p>`}
    </article>`;})}
  </div>
  ${!LS.views.length?empty('No loans or IOUs yet. Use “Add a loan” to track money you owe or are owed.'):null}
  <p style="margin:0;font-size:13px;color:#5a6b63;text-wrap:pretty">Loans you add here are saved in your private database and shared with the assistant when you ask questions. Payoff dates assume the same payment every month.</p>`;
}

export const Pages={overview:Overview,spending:Spending,recurring:Recurring,loans:Loans,projections:Projections,transactions:Transactions,chat:Chat,settings:Settings};
